#!/usr/bin/env python3
"""Install the second-generation sample-based guitar renderer."""
from pathlib import Path
import os

root = Path(os.environ["PROJECT_DIR"])
path = root / "app/src/main/java/de/saitenwerk/app/MainActivity.kt"
s = path.read_text(encoding="utf-8")

start = s.find("    private class GuitarPlayerEngine(")
if start < 0:
    raise SystemExit("ERROR: GuitarPlayerEngine start not found.")
end = s.find("    override fun onCreateView(", start)
if end < 0:
    raise SystemExit("ERROR: GuitarPlayerEngine end anchor not found.")

new_class = "    private class GuitarPlayerEngine(private val context: android.content.Context) {\n        /*\n         * Generation 2:\n         * real steel-string samples + six-string voicings + beat-aware down/up strumming.\n         */\n        private val sampleRate = 22_050\n        private val chunkFrames = 512\n        private val stringTuning = intArrayOf(40, 45, 50, 55, 59, 64) // E2 A2 D3 G3 B3 E4\n        private var audioTrack: AudioTrack? = null\n        private var renderThread: Thread? = null\n        @Volatile private var cancelled = false\n        @Volatile private var running = false\n        @Volatile private var paused = false\n        private var totalDurationMs = 0\n\n        private data class GuitarSample(val rootMidi: Int, val samples: FloatArray)\n        private data class GuitarStringNote(val midi: Int, val stringIndex: Int, val fret: Int)\n\n        fun stop() {\n            cancelled = true\n            running = false\n            paused = false\n            renderThread?.interrupt()\n            renderThread = null\n            audioTrack?.let {\n                try { it.stop() } catch (_: Exception) {}\n                try { it.release() } catch (_: Exception) {}\n            }\n            audioTrack = null\n        }\n\n        fun pause() {\n            audioTrack?.pause()\n            paused = true\n            running = false\n        }\n\n        fun resume() {\n            audioTrack?.play()\n            paused = false\n            running = true\n        }\n\n        fun position(): Int {\n            val track = audioTrack ?: return 0\n            val frames = track.playbackHeadPosition.toLong() and 0xffffffffL\n            return ((frames * 1000L) / sampleRate).toInt().coerceIn(0, totalDurationMs)\n        }\n\n        fun duration(): Int = totalDurationMs\n\n        fun play(\n            timeline: SongTimeline,\n            onReady: (Int) -> Unit,\n            onCompleted: () -> Unit,\n            onError: (Throwable) -> Unit\n        ) {\n            stop()\n            cancelled = false\n            val beatMs = 60_000.0 / timeline.tempoBpm.coerceIn(40, 180)\n            totalDurationMs = timeline.durationMs.toInt().coerceAtLeast(1000)\n\n            try {\n                val minBuffer = AudioTrack.getMinBufferSize(\n                    sampleRate,\n                    AudioFormat.CHANNEL_OUT_STEREO,\n                    AudioFormat.ENCODING_PCM_16BIT\n                ).coerceAtLeast(chunkFrames * 2 * 4)\n\n                val track = AudioTrack.Builder()\n                    .setAudioAttributes(AudioAttributes.Builder()\n                        .setUsage(AudioAttributes.USAGE_MEDIA)\n                        .setContentType(AudioAttributes.CONTENT_TYPE_MUSIC)\n                        .build())\n                    .setAudioFormat(AudioFormat.Builder()\n                        .setSampleRate(sampleRate)\n                        .setEncoding(AudioFormat.ENCODING_PCM_16BIT)\n                        .setChannelMask(AudioFormat.CHANNEL_OUT_STEREO)\n                        .build())\n                    .setBufferSizeInBytes(minBuffer)\n                    .setTransferMode(AudioTrack.MODE_STREAM)\n                    .build()\n                audioTrack = track\n\n                val chordEvents = timeline.chords.map { Triple(it.chord, it.startMs, it.endMs) }\n                val melody = timeline.melody\n                val chordVoicings = chordEvents.map { guitarVoicing(it.first) }\n                val requiredMidi = (\n                    melody.map { it.midi } +\n                    chordVoicings.flatten().map { it.midi }\n                ).distinct()\n                val samples = requiredMidi.associateWith { midi ->\n                    loadGuitarSample(midi) ?: GuitarSample(midi, buildFallbackPluck(midi))\n                }\n\n                track.play()\n                running = true\n                onReady(totalDurationMs)\n\n                renderThread = Thread {\n                    try {\n                        val buffer = ShortArray(chunkFrames * 2)\n                        val totalFrames = totalDurationMs * sampleRate / 1000L\n                        var frameCursor = 0L\n\n                        while (!cancelled && frameCursor < totalFrames) {\n                            while (paused && !cancelled) Thread.sleep(8L)\n                            if (cancelled) break\n\n                            var count = 0\n                            while (count < chunkFrames && frameCursor < totalFrames) {\n                                val ms = frameCursor * 1000L / sampleRate\n                                var left = 0.0\n                                var right = 0.0\n\n                                // One guitar strum on every beat of the active chord.\n                                // Alternating down/up motion is much closer to a played guitar\n                                // than repeatedly triggering a static triad.\n                                for (ci in chordEvents.indices) {\n                                    val ev = chordEvents[ci]\n                                    if (ms < ev.second || ms >= ev.third) continue\n\n                                    val localMs = ms - ev.second\n                                    val beatIndex = kotlin.math.floor(localMs / beatMs).toInt()\n                                    val beatStart = beatIndex * beatMs\n                                    if (localMs < beatStart || localMs >= beatStart + 115.0) continue\n\n                                    val down = beatIndex % 2 == 0\n                                    val strumAge = (localMs - beatStart) / 1000.0\n                                    val voicing = chordVoicings[ci]\n\n                                    for (j in voicing.indices) {\n                                        val order = if (down) j else (voicing.lastIndex - j)\n                                        val note = voicing[order]\n                                        val stringDelay = if (down) order * 0.0105 else order * 0.0095\n                                        val t = strumAge - stringDelay\n                                        if (t < 0.0) continue\n\n                                        val accent = if (beatIndex % 4 == 0) 1.0 else 0.86\n                                        val stringWeight = 0.88 + note.stringIndex * 0.018\n                                        val velocity = 0.12 * accent * stringWeight\n                                        val mono = guitarSample(samples[note.midi], note.midi, t, velocity)\n\n                                        val pan = ((note.stringIndex - 2.5) / 3.5) * 0.34\n                                        left += mono * (1.0 - pan)\n                                        right += mono * (1.0 + pan)\n                                    }\n                                }\n\n                                // Melody remains present but no longer dominates the guitar bed.\n                                val melodyNote = melody.firstOrNull {\n                                    ms >= it.startMs && ms < it.startMs + it.durationMs\n                                }\n                                if (melodyNote != null) {\n                                    val local = (ms - melodyNote.startMs) / 1000.0\n                                    val mono = guitarSample(\n                                        samples[melodyNote.midi],\n                                        melodyNote.midi,\n                                        local,\n                                        melodyNote.velocity.toDouble() * 0.48\n                                    )\n                                    left += mono * 0.98\n                                    right += mono * 1.02\n                                }\n\n                                // Acoustic body bloom derived from the actual played signal,\n                                // not a fixed synthetic oscillator.\n                                val body = (left + right) * 0.018\n                                left += body\n                                right += body\n\n                                val l = softLimit(left * 0.86)\n                                val r = softLimit(right * 0.86)\n                                buffer[count * 2] =\n                                    (l * 32767.0).roundToInt().coerceIn(-32768, 32767).toShort()\n                                buffer[count * 2 + 1] =\n                                    (r * 32767.0).roundToInt().coerceIn(-32768, 32767).toShort()\n                                count++\n                                frameCursor++\n                            }\n\n                            var writtenFrames = 0\n                            while (writtenFrames < count && !cancelled) {\n                                val n = track.write(\n                                    buffer,\n                                    writtenFrames * 2,\n                                    (count - writtenFrames) * 2,\n                                    AudioTrack.WRITE_BLOCKING\n                                )\n                                if (n <= 0) break\n                                writtenFrames += n / 2\n                            }\n                        }\n\n                        if (!cancelled) {\n                            running = false\n                            try { track.stop() } catch (_: Exception) {}\n                            onCompleted()\n                        }\n                    } catch (t: Throwable) {\n                        if (!cancelled) onError(t)\n                    }\n                }.also { it.start() }\n            } catch (t: Throwable) {\n                onError(t)\n            }\n        }\n\n        private fun guitarVoicing(chord: String): List<GuitarStringNote> {\n            val clean = chord.replace('♯', '#').replace('♭', 'b')\n            val match = Regex(\"^([A-G](?:#|b)?)([^/]*)(?:/([A-G](?:#|b)?))?\").find(clean)\n                ?: return listOf(\n                    GuitarStringNote(52, 0, 12),\n                    GuitarStringNote(55, 1, 10),\n                    GuitarStringNote(59, 2, 9)\n                )\n\n            val rootPc = noteIndex(match.groupValues[1]) ?: 0\n            val bassPc = match.groupValues[3].takeIf { it.isNotBlank() }?.let { noteIndex(it) }\n            val suffix = match.groupValues[2].lowercase()\n\n            val chordPcs = when {\n                suffix.contains(\"dim\") -> setOf(rootPc, (rootPc + 3) % 12, (rootPc + 6) % 12)\n                suffix.contains(\"sus4\") -> setOf(rootPc, (rootPc + 5) % 12, (rootPc + 7) % 12)\n                suffix.contains(\"sus2\") -> setOf(rootPc, (rootPc + 2) % 12, (rootPc + 7) % 12)\n                suffix.contains(\"maj7\") -> setOf(rootPc, (rootPc + 4) % 12, (rootPc + 7) % 12, (rootPc + 11) % 12)\n                suffix.contains(\"7\") -> setOf(rootPc, (rootPc + 4) % 12, (rootPc + 7) % 12, (rootPc + 10) % 12)\n                suffix.contains(\"m\") && !suffix.contains(\"maj\") -> setOf(rootPc, (rootPc + 3) % 12, (rootPc + 7) % 12)\n                else -> setOf(rootPc, (rootPc + 4) % 12, (rootPc + 7) % 12)\n            }\n\n            val candidates = stringTuning.mapIndexed { string, open ->\n                (0..7).mapNotNull { fret ->\n                    val midi = open + fret\n                    if (midi % 12 in chordPcs) GuitarStringNote(midi, string, fret) else null\n                }.sortedWith(\n                    compareBy<GuitarStringNote> {\n                        if (bassPc != null && it.midi % 12 == bassPc) 0 else 1\n                    }.thenBy { it.fret }\n                )\n            }\n\n            val chosen = MutableList<GuitarStringNote?>(6) { null }\n            val covered = mutableSetOf<Int>()\n\n            for (string in 0 until 6) {\n                val options = candidates[string]\n                val best = options.firstOrNull {\n                    it.midi % 12 == (bassPc ?: rootPc) && string <= 1\n                } ?: options.firstOrNull()\n                if (best != null) {\n                    chosen[string] = best\n                    covered.add(best.midi % 12)\n                }\n            }\n\n            for (pc in chordPcs) {\n                if (covered.contains(pc)) continue\n                val replacement = candidates.withIndex()\n                    .flatMap { (string, opts) -> opts.map { string to it } }\n                    .firstOrNull { (_, note) -> note.midi % 12 == pc }\n                if (replacement != null) {\n                    chosen[replacement.first] = replacement.second\n                    covered.add(pc)\n                }\n            }\n\n            val result = chosen.filterNotNull()\n                .distinctBy { it.stringIndex }\n                .sortedBy { it.stringIndex }\n\n            return if (result.size >= 3) result else fallbackTriad(rootPc)\n        }\n\n        private fun fallbackTriad(rootPc: Int): List<GuitarStringNote> {\n            val base = 52 + rootPc\n            return listOf(\n                GuitarStringNote(base, 0, (base - 40).coerceAtLeast(0)),\n                GuitarStringNote(base + 4, 1, (base + 4 - 45).coerceAtLeast(0)),\n                GuitarStringNote(base + 7, 2, (base + 7 - 50).coerceAtLeast(0))\n            )\n        }\n\n        private fun loadGuitarSample(targetMidi: Int): GuitarSample? {\n            val sourceMidi = targetMidi.coerceIn(40, 84)\n            return try {\n                val bytes = context.assets.open(\"guitar_samples/note_\" + sourceMidi + \".pcm\").use { it.readBytes() }\n                val count = bytes.size / 2\n                if (count < 2048) return null\n                val pcm = FloatArray(count)\n                for (i in 0 until count) {\n                    val lo = bytes[i * 2].toInt() and 0xff\n                    val hi = bytes[i * 2 + 1].toInt()\n                    val value = (hi shl 8) or lo\n                    pcm[i] = value.toShort() / 32768.0f\n                }\n                GuitarSample(sourceMidi, pcm)\n            } catch (_: Exception) {\n                null\n            }\n        }\n\n        private fun guitarSample(\n            sample: GuitarSample?,\n            targetMidi: Int,\n            t: Double,\n            velocity: Double\n        ): Double {\n            if (sample == null || t < 0.0) return 0.0\n            val rate = 2.0.pow((targetMidi - sample.rootMidi) / 12.0)\n            val position = t * sampleRate * rate\n            val index = position.toInt()\n            if (index !in sample.samples.indices) return 0.0\n            val frac = position - index\n            val a = sample.samples[index].toDouble()\n            val b = if (index + 1 < sample.samples.size) sample.samples[index + 1].toDouble() else a\n            val value = a + (b - a) * frac\n            val attack = (t / 0.0018).coerceAtMost(1.0)\n            return value * velocity * attack\n        }\n\n        private fun buildFallbackPluck(midi: Int): FloatArray {\n            val frequency = midiToHz(midi)\n            val delay = (sampleRate / frequency).roundToInt().coerceIn(2, sampleRate / 2)\n            val line = FloatArray(delay)\n            var random = (midi.toLong() * 7919L + 104729L) and 0x7fffffffL\n            for (i in line.indices) {\n                random = (random * 1103515245L + 12345L) and 0x7fffffffL\n                line[i] = ((random.toDouble() / 1073741823.5) - 1.0).toFloat() * 0.45f\n            }\n            val output = FloatArray(sampleRate * 2)\n            var cursor = 0\n            for (i in output.indices) {\n                val current = line[cursor]\n                val next = line[(cursor + 1) % delay]\n                line[cursor] = (current * 0.52f + next * 0.48f) * 0.9995f\n                output[i] = current\n                cursor = (cursor + 1) % delay\n            }\n            return output\n        }\n\n        private fun softLimit(value: Double): Double =\n            value / (1.0 + kotlin.math.abs(value) * 0.35)\n\n        private fun midiToHz(midi: Int): Double =\n            440.0 * 2.0.pow((midi - 69) / 12.0)\n\n        private fun noteIndex(note: String): Int? = when (note) {\n            \"C\" -> 0\n            \"C#\", \"Db\" -> 1\n            \"D\" -> 2\n            \"D#\", \"Eb\" -> 3\n            \"E\" -> 4\n            \"F\" -> 5\n            \"F#\", \"Gb\" -> 6\n            \"G\" -> 7\n            \"G#\", \"Ab\" -> 8\n            \"A\" -> 9\n            \"A#\", \"Bb\" -> 10\n            \"B\" -> 11\n            else -> null\n        }\n    }\n\n"
s = s[:start] + new_class + s[end:]

required = [
    "private val stringTuning = intArrayOf(40, 45, 50, 55, 59, 64)",
    "private fun guitarVoicing(chord: String)",
    "One guitar strum on every beat",
    "AudioFormat.CHANNEL_OUT_STEREO",
    "private fun softLimit(value: Double)",
    "private fun guitarSample("
]
missing = [x for x in required if x not in s]
if missing:
    raise SystemExit("ERROR: Generation-2 guitar engine validation failed: " + ", ".join(missing))

path.write_text(s, encoding="utf-8")
print("REALISTIC GUITAR ENGINE V2: PASS")
print("Recorded samples + six-string voicings + beat-aware down/up strumming + stereo rendering installed.")
